import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const deliverTo = async (h: any, to: string, action: string) => {
  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
  assert.ok(m, `no ${action} to ${to}`);
  await h.deliver(m.id);
};
const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1 });

test('initial state and queries', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('run'), null);
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('nope')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start, both complete', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}],
  ]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('a first failure is retried; a retried task then completes', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  await deliverTo(h, 'run', 'Report');
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  const [a] = await h.inFlight();
  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker1', 'Assign', {}]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, true));
});

test('a second failure is recorded', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
});

test('cancel aborts only assigned tasks; abort before assign is ignored', async () => {
  const h: any = await createHost();
  await h.start();
  await deliverTo(h, 'worker0', 'Assign');
  await h.workDone('worker0');
  await deliverTo(h, 'run', 'Report');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
  assert.deepEqual(aborts.map((m: any) => m.to), ['worker1']);
  await deliverTo(h, 'worker1', 'Abort'); // reaches an idle worker: ignored
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  await h.deliverAll(); // Assign arrives late
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.run()).status, 'cancelling');
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('cancel with both busy', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.cancel(); await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'cancelled', 'cancelled'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('a failure while cancelling is not retried', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel(); // task0 still assigned at the run: Abort to worker0 (ignored), worker1
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

