import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const deliverTo = async (h: any, to: string, action: string) => {
  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
  assert.ok(m, `no ${action} to ${to}`);
  await h.deliver(m.id);
};
const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1 });

test('initial state and queries', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('run'), null);
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('nope')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start, both complete', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}],
  ]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('a first failure is retried; a retried task then completes', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  await deliverTo(h, 'run', 'Report');
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  const [a] = await h.inFlight();
  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker1', 'Assign', {}]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, true));
});

test('a second failure is recorded', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
});

test('cancel aborts only assigned tasks; abort before assign is ignored', async () => {
  const h: any = await createHost();
  await h.start();
  await deliverTo(h, 'worker0', 'Assign');
  await h.workDone('worker0');
  await deliverTo(h, 'run', 'Report');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
  assert.deepEqual(aborts.map((m: any) => m.to), ['worker1']);
  await deliverTo(h, 'worker1', 'Abort'); // reaches an idle worker: ignored
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  await h.deliverAll(); // Assign arrives late
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.run()).status, 'cancelling');
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('cancel with both busy', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.cancel(); await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'cancelled', 'cancelled'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('a failure while cancelling is not retried', async () => {
  const h: any = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel(); // task0 still assigned at the run: Abort to worker0 (ignored), worker1
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

// T7, a run and its workers: the run assigns its two tasks, each to its own worker, and records their reports.
import {
  module, enumType, machine, field, t, action, on, require, set, when, send, terminal, invariant, isIn, implies,
  configuration, instance,
} from '@cognitive-fab/poly/embed';

export default module('runs', [
  // One vocabulary for every status: the run's, its tasks', a report's outcome and a worker's.
  enumType('St', ['idle', 'busy', 'running', 'cancelling', 'assigned', 'completed', 'failed', 'cancelled']),

  machine('Run', {
    state: {
      status: field(t.named('St'), ($) => $.idle),
      task0: field(t.named('St'), ($) => $.idle),
      task1: field(t.named('St'), ($) => $.idle),
      w0: field(t.ref('Worker'), ($) => $.none),
      w1: field(t.ref('Worker'), ($) => $.none),
      retried0: field(t.bool, () => false),
      retried1: field(t.bool, () => false),
    },
    items: [
      terminal(($) => isIn($.status, [$.completed, $.failed, $.cancelled])),
      action('Start', {}),
      action('Cancel', {}),
      action('TaskTimeout', { task: t.range(0, 1) }),
      action('Report', { task: t.range(0, 1), outcome: t.named('St') }),

      on('Start', ($) => [
        require($.status === $.idle, 'already-started'),
        set('status', $.running),
        set('task0', $.assigned),
        set('task1', $.assigned),
        send($.w0, 'Assign', {}),
        send($.w1, 'Assign', {}),
      ]),

      on('Cancel', ($) => [
        require($.status === $.running, 'not-running'),
        set('status', $.cancelling),
        when($.task0 === $.assigned, [send($.w0, 'Abort', {})]),
        when($.task1 === $.assigned, [send($.w1, 'Abort', {})]),
      ]),

      // A report sets its task's status; the run ends once both tasks have reported.
      on('Report', ($) => [
        require(isIn($.status, [$.running, $.cancelling]), 'run-ended'),
        require(isIn($.outcome, [$.completed, $.failed, $.cancelled]), 'not-an-outcome'),
        require(($.task === 0 && $.task0 === $.assigned) || ($.task === 1 && $.task1 === $.assigned), 'already-reported'),
        when($.task === 0, [
          // A first failure while running is retried: the task stays assigned and its worker is assigned again.
          when($.outcome === $.failed && $.status === $.running && !$.retried0, [
            set('retried0', true),
            send($.w0, 'Assign', {}),
          ], [
            set('task0', $.outcome),
            when($.task1 !== $.assigned, [
              when($.outcome === $.completed && $.task1 === $.completed, [set('status', $.completed)], [
                when($.outcome === $.failed || $.task1 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
              ]),
            ]),
          ]),
        ], [
          when($.outcome === $.failed && $.status === $.running && !$.retried1, [
            set('retried1', true),
            send($.w1, 'Assign', {}),
          ], [
            set('task1', $.outcome),
            when($.task0 !== $.assigned, [
              when($.outcome === $.completed && $.task0 === $.completed, [set('status', $.completed)], [
                when($.outcome === $.failed || $.task0 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
              ]),
            ]),
          ]),
        ]),
      ], ['task', 'outcome']),

      // A timeout fails a task still assigned for good (no retry) and aborts its worker; its later report is ignored.
      on('TaskTimeout', ($) => [
        require(isIn($.status, [$.running, $.cancelling]), 'not-running'),
        require(($.task === 0 && $.task0 === $.assigned) || ($.task === 1 && $.task1 === $.assigned), 'not-assigned'),
        when($.task === 0, [
          set('task0', $.failed),
          when($.task1 !== $.assigned, [set('status', $.failed)]),
          send($.w0, 'Abort', {}),
        ], [
          set('task1', $.failed),
          when($.task0 !== $.assigned, [set('status', $.failed)]),
          send($.w1, 'Abort', {}),
        ]),
      ], ['task']),

      invariant('completed-when-both-completed', ($) =>
        implies($.status === $.completed, $.task0 === $.completed && $.task1 === $.completed)),
      invariant('ended-when-both-reported', ($) =>
        implies(isIn($.status, [$.completed, $.failed, $.cancelled]), $.task0 !== $.assigned && $.task1 !== $.assigned)),
      invariant('failed-when-a-task-failed', ($) =>
        implies($.status === $.failed, $.task0 === $.failed || $.task1 === $.failed)),
    ],
  }),

  // A worker serves its task for as long as the system lives: it has no terminal state.
  machine('Worker', {
    service: true,
    state: {
      status: field(t.named('St'), ($) => $.idle),
      task: field(t.range(0, 1), () => 0),
      run: field(t.ref('Run'), ($) => $.none),
    },
    items: [
      action('Assign', {}),
      action('Abort', {}),
      action('WorkDone', {}),
      action('WorkFailed', {}),

      on('Assign', ($) => [require($.status === $.idle, 'busy'), set('status', $.busy)]),
      // An Abort that reaches an idle worker is ignored: a rejected step changes nothing.
      on('Abort', ($) => [
        require($.status === $.busy, 'not-busy'),
        set('status', $.idle),
        send($.run, 'Report', { task: $.task, outcome: $.cancelled }),
      ]),
      on('WorkDone', ($) => [
        require($.status === $.busy, 'not-busy'),
        set('status', $.idle),
        send($.run, 'Report', { task: $.task, outcome: $.completed }),
      ]),
      on('WorkFailed', ($) => [
        require($.status === $.busy, 'not-busy'),
        set('status', $.idle),
        send($.run, 'Report', { task: $.task, outcome: $.failed }),
      ]),
    ],
  }),

  configuration('system', {
    instances: [
      instance('run', 'Run', { init: ($) => ({ w0: $.worker0, w1: $.worker1 }) }),
      instance('worker0', 'Worker', { init: ($) => ({ task: 0, run: $.run }) }),
      instance('worker1', 'Worker', { init: ($) => ({ task: 1, run: $.run }) }),
    ],
    inputs: ['run.Start', 'run.Cancel', 'run.TaskTimeout', 'worker0.WorkDone', 'worker0.WorkFailed', 'worker1.WorkDone', 'worker1.WorkFailed'],
    bounds: { transit: 4 },
    properties: [
      invariant('completed-only-when-both-completed', ($) =>
        implies($.run.status === $.completed, $.run.task0 === $.completed && $.run.task1 === $.completed)),
      // A timeout may end the run before its worker stops, but a completed run waited for both workers.
      invariant('completed-only-when-workers-idle', ($) =>
        implies($.run.status === $.completed, $.worker0.status === $.idle && $.worker1.status === $.idle)),
    ],
  }),
]);

