1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import createHost from '../build/host.gen.ts';
4	
5	const deliverTo = async (h: any, to: string, action: string) => {
6	  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
7	  assert.ok(m, `no ${action} to ${to}`);
8	  await h.deliver(m.id);
9	};
10	const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
11	  ({ status, task0, task1, retried0, retried1 });
12	
13	test('initial state and queries', async () => {
14	  const h: any = await createHost();
15	  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
16	  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
17	  assert.equal(await h.worker('run'), null);
18	  assert.equal(await h.worker('nope'), null);
19	  assert.equal((await h.workDone('worker0')).ok, false);
20	  assert.equal((await h.workDone('nope')).ok, false);
21	  assert.equal((await h.cancel()).ok, false);
22	});
23	
24	test('start, both complete', async () => {
25	  const h: any = await createHost();
26	  assert.deepEqual(await h.start(), { ok: true });
27	  assert.equal((await h.start()).ok, false);
28	  const msgs = await h.inFlight();
29	  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [
30	    ['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}],
31	  ]);
32	  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
33	  await h.deliverAll();
34	  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
35	  assert.deepEqual(await h.workDone('worker0'), { ok: true });
36	  const [r] = await h.inFlight();
37	  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
38	  await h.deliverAll();
39	  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
40	  await h.workDone('worker1');
41	  await h.deliverAll();
42	  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
43	});
44	
45	test('a first failure is retried; a retried task then completes', async () => {
46	  const h: any = await createHost();
47	  await h.start(); await h.deliverAll();
48	  await h.workFailed('worker1');
49	  await deliverTo(h, 'run', 'Report');
50	  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
51	  const [a] = await h.inFlight();
52	  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker1', 'Assign', {}]);
53	  await h.deliverAll();
54	  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
55	  await h.workDone('worker1'); await h.workDone('worker0'); await h.deliverAll();
56	  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, true));
57	});
58	
59	test('a second failure is recorded', async () => {
60	  const h: any = await createHost();
61	  await h.start(); await h.deliverAll();
62	  await h.workFailed('worker1'); await h.deliverAll();
63	  await h.workFailed('worker1'); await h.deliverAll();
64	  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
65	  await h.workDone('worker0'); await h.deliverAll();
66	  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
67	});
