69	test('cancel aborts only assigned tasks; abort before assign is ignored', async () => {
70	  const h: any = await createHost();
71	  await h.start();
72	  await deliverTo(h, 'worker0', 'Assign');
73	  await h.workDone('worker0');
74	  await deliverTo(h, 'run', 'Report');
75	  assert.deepEqual(await h.cancel(), { ok: true });
76	  assert.equal((await h.cancel()).ok, false);
77	  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
78	  assert.deepEqual(aborts.map((m: any) => m.to), ['worker1']);
79	  await deliverTo(h, 'worker1', 'Abort'); // reaches an idle worker: ignored
80	  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
81	  await h.deliverAll(); // Assign arrives late
82	  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
83	  assert.equal((await h.run()).status, 'cancelling');
84	  await h.workDone('worker1'); await h.deliverAll();
85	  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
86	});
