90	  await h.start(); await h.deliverAll();
91	  await h.cancel(); await h.deliverAll();
92	  assert.deepEqual(await h.run(), view('cancelled', 'cancelled', 'cancelled'));
93	  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
94	});
